from __future__ import annotations

def _attr(key, name, data_type, description, sort_order, *, choices=None):
    config = {"choices": choices} if choices is not None else {}
    return {"key": key, "name": name, "data_type": data_type,
            "description": description, "required": False, "nullable": True,
            "default_value": None, "sort_order": sort_order, "config": config}

def _otype(key, name, description, sort_order, attributes=()):
    return {"key": key, "name": name, "description": description,
            "sort_order": sort_order, "attributes": list(attributes)}

def _rule(subject_type, object_type, subject_minimum, subject_maximum,
          object_minimum, object_maximum):
    return {"subject_type": subject_type, "object_type": object_type,
            "subject_minimum": object_minimum, "subject_maximum": object_maximum,
            "object_minimum": subject_minimum, "object_maximum": subject_maximum}

def _rtype(key, name, description, sort_order, rules):
    return {"key": key, "name": name, "description": description,
            "sort_order": sort_order, "rules": rules, "attributes": []}

